1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Events;
6	
7	use App\Enums\UserRole;
8	use App\Models\Team;
9	use App\Models\User;
10	use App\Modules\Events\Enums\EventState;
11	use App\Modules\Events\Models\Event;
12	use App\Modules\Events\Models\LandingPage;
13	use Illuminate\Support\Facades\Cache;
14	use PHPUnit\Framework\Attributes\Group;
15	use PHPUnit\Framework\Attributes\Test;
16	use Tests\Feature\FeatureTestCase;
17	
18	/**
19	 * Capsule T5 ATDD — Shareable landing-preview link for unauthenticated reviewers.
20	 *
21	 * Covers:
22	 *  - AC1 organiser with the event-update capability mints a link via POST events.landing.share
23	 *  - AC2 GET events.public.landing-share serves an unauthenticated read-only preview, DRAFT included
24	 *  - AC3 tamper-evident and time-limited: altered parameters and expired links are refused
25	 *  - AC4 a link minted for one event does not grant access to another event
26	 *  - AC5 an actor without the event-update capability cannot mint a link
27	 *  - AC6 the shared view carries no registration submission and no authoring control, and
28	 *        visiting it neither authenticates the visitor nor opens the authenticated editor
29	 *
30	 * Contract this test pins for the implementer:
31	 *  - POST events.landing.share responds successfully with JSON {"url": "<absolute share link>"}
32	 *  - the minted link is event-scoped (the event uuid appears in it) and signed by the
33	 *    framework's signed-URL mechanism, so refusals surface as HTTP 403
34	 *  - the shared surface renders with data-testid="landing-share-preview"
35	 *
36	 * ALL tests intentionally FAIL on HEAD: neither route exists, so no share link can be
37	 * minted and no unauthenticated read-only preview can be served.
38	 */
39	#[Group('events')]
40	#[Group('p1')]
41	class LandingPreviewShareLinkTest extends FeatureTestCase
42	{
43	    protected function setUp(): void
44	    {
45	        parent::setUp();
46	        Cache::flush();
47	    }
48	
49	    /**
50	     * @return array{0: User, 1: Team, 2: Event}
51	     */
52	    private function organiserWithDraftEvent(string $title = 'Draft Product Ops Briefing'): array
53	    {
54	        $organiser = User::factory()->create();
55	        $team = Team::factory()->create(['user_id' => $organiser->id]);
56	        $organiser->teams()->attach($team, ['role' => UserRole::ADMIN->value]);
57	        $organiser->forceFill(['current_team_id' => $team->id])->save();
58	
59	        $event = Event::factory()
60	            ->inState(EventState::DRAFT)
61	            ->for($team)
62	            ->create([
63	                'created_by' => $organiser->id,
64	                'title' => $title,
65	            ]);
66	
67	        LandingPage::factory()->for($event)->create([
68	            'team_id' => $event->team_id,
69	            'template' => 'modern',
70	            'primary_color' => '#112233',
71	        ]);
72	
73	        return [$organiser->fresh(), $team->fresh(), $event->fresh()];
74	    }
75	
76	    private function mintShareLink(User $organiser, Event $event): string
77	    {
78	        $response = $this->actingAs($organiser)
79	            ->postJson(route('events.landing.share', $event));
80	
81	        $response->assertSuccessful();
82	
83	        $url = $response->json('url');
84	
85	        $this->assertIsString($url, 'Minting a share link must return the share url.');
86	        $this->assertNotSame('', $url);
87	
88	        return $url;
89	    }
90	
91	    private function becomeGuest(): void
92	    {
93	        $this->app->make('auth')->forgetGuards();
94	        $this->flushSession();
95	    }
96	
97	    #[Test]
98	    public function organiser_mints_link_that_serves_unauthenticated_read_only_preview_of_draft_event(): void
99	    {
100	        [$organiser, , $event] = $this->organiserWithDraftEvent();
101	
102	        $url = $this->mintShareLink($organiser, $event);
103	        $this->assertStringContainsString($event->uuid, $url, 'The share link must be scoped to one event.');
104	
105	        $this->becomeGuest();
106	
107	        $response = $this->get($url);
108	
109	        $response->assertOk();
110	        $response->assertSee('data-testid="landing-share-preview"', false);
111	        $response->assertSeeText($event->title);
112	        $this->assertSame(EventState::DRAFT, $event->fresh()->state);
113	    }
114	
115	    #[Test]
116	    public function shared_view_exposes_no_registration_or_authoring_surface_and_does_not_authenticate_the_visitor(): void
117	    {
118	        [$organiser, , $event] = $this->organiserWithDraftEvent();
119	
120	        $url = $this->mintShareLink($organiser, $event);
121	
122	        $this->becomeGuest();
123	
124	        $response = $this->get($url);
125	
126	        $response->assertOk();
127	        $response->assertDontSee('data-testid="public-landing-register-form"', false);
128	        $response->assertDontSee("/webinars/{$event->uuid}/register", false);
129	        $response->assertDontSee('name="_token"', false);
130	
131	        $this->assertGuest();
132	        $this->get(route('events.landing.edit', $event))->assertRedirect();
133	    }
134	
135	    #[Test]
136	    public function tampered_share_link_is_refused(): void
137	    {
138	        [$organiser, , $event] = $this->organiserWithDraftEvent();
139	
140	        $url = $this->mintShareLink($organiser, $event);
141	
142	        $this->becomeGuest();
143	
144	        $tampered = $url.(str_contains($url, '?') ? '&' : '?').'reviewer=elevated';
145	
146	        $this->get($tampered)->assertForbidden();
147	    }
148	
149	    #[Test]
150	    public function expired_share_link_is_refused(): void
151	    {
152	        [$organiser, , $event] = $this->organiserWithDraftEvent();
153	
154	        $url = $this->mintShareLink($organiser, $event);
155	
156	        $this->becomeGuest();
157	        $this->travel(1)->years();
158	
159	        $this->get($url)->assertForbidden();
160	    }
161	
162	    #[Test]
163	    public function share_link_for_one_event_does_not_grant_access_to_another_event(): void
164	    {
165	        [$organiser, $team, $event] = $this->organiserWithDraftEvent();
166	
167	        $otherEvent = Event::factory()
168	            ->inState(EventState::DRAFT)
169	            ->for($team)
170	            ->create([
171	                'created_by' => $organiser->id,
172	                'title' => 'Unshared Internal Roadmap Session',
173	            ]);
174	        LandingPage::factory()->for($otherEvent)->create(['team_id' => $otherEvent->team_id]);
175	
176	        $url = $this->mintShareLink($organiser, $event);
177	
178	        $this->becomeGuest();
179	
180	        $crossEventUrl = str_replace($event->uuid, $otherEvent->uuid, $url);
181	        $this->assertNotSame($url, $crossEventUrl);
182	
183	        $this->get($crossEventUrl)->assertForbidden();
184	        $this->get($url)->assertOk()->assertDontSeeText($otherEvent->title);
185	    }
186	
187	    #[Test]
188	    public function actor_without_event_update_capability_cannot_mint_share_link(): void
189	    {
190	        [, $team, $event] = $this->organiserWithDraftEvent();
191	
192	        $billingAdmin = User::factory()->create();
193	        $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
194	        $billingAdmin->forceFill(['current_team_id' => $team->id])->save();
195	
196	        $this->actingAs($billingAdmin->fresh())
197	            ->postJson(route('events.landing.share', $event))
198	            ->assertForbidden();
199	    }
200	}
