2	
3	declare(strict_types=1);
4	
5	namespace App\Modules\Events\Http\Controllers;
6	
7	use App\Modules\Events\Enums\EventState;
8	use App\Modules\Events\Models\Event;
9	use App\Modules\Events\Models\LandingPage;
10	use App\Modules\Events\Models\Registration;
11	use App\Modules\Events\Services\EventService;
12	use App\Modules\Events\Services\RegistrantAccessUrlService;
13	use App\Modules\Events\Support\LandingPreviewPayload;
14	use App\Modules\Events\Support\LocaleResolver;
15	use App\Modules\Events\Support\RegistrationFormConfigPayload;
16	use App\Modules\Streaming\Services\ReplayPresentationService;
17	use Illuminate\Http\Request;
18	use Illuminate\Routing\Controller;
19	use Symfony\Component\HttpFoundation\Response;
20	
21	class PublicLandingController extends Controller
22	{
23	    public function __construct(
24	        private readonly EventService $eventService,
25	        private readonly ReplayPresentationService $replays,
26	        private readonly RegistrantAccessUrlService $registrantAccessUrls,
27	    ) {}
28	
29	    public function show(Request $request, string $eventUuid): Response
30	    {
31	        $event = $this->eventService->findPublicLandingEvent($eventUuid);
32	
33	        if ($event === null) {
34	            abort(404);
35	        }
36	
37	        if ($this->shouldHideCompletely($event)) {
38	            abort(404);
39	        }
40	
41	        // Story 3-11 / FR106 / AC2 — set the request locale to the event's configured
42	        // language so public landing chrome renders in the organizer's chosen locale.
43	        // Per-request only: Laravel re-bootstraps locale from config on every new request,
44	        // so this call cannot leak to a subsequent request in the test kernel or production.
45	        app()->setLocale($this->resolveEventLocale($event));
46	
47	        $landing = $event->landingPage;
48	        $previewData = $landing instanceof LandingPage
49	            ? $landing->previewPayload($event)
50	            : LandingPreviewPayload::build($event, []);
51	        $formConfig = $landing instanceof LandingPage
52	            ? $landing->registrationFormConfigPayload()
53	            : RegistrationFormConfigPayload::build([]);
54	        $shell = $this->shellFor($event);
55	        $registrantContext = $shell === 'landing'
56	            ? $this->resolveRegistrantContext($event, $request)
57	            : ['registration' => null, 'viewer_shell' => null, 'access_error' => null];
58	
59	        $replayPresentation = $registrantContext['viewer_shell'] === 'ended'
60	            && $registrantContext['registration'] instanceof Registration
61	                ? $this->replays->forEvent($event, $registrantContext['registration'])
62	                : null;
63	
64	        return response()->view('events::public.show', [
65	            'event' => $event,
66	            'previewData' => $previewData,
67	            'formConfig' => $formConfig,
68	            'shell' => $shell,
69	            'registrationOpen' => $this->registrationOpen($event, $registrantContext['registration']),
70	            'registrant' => $registrantContext['registration'],
71	            'viewerShell' => $registrantContext['viewer_shell'],
72	            'accessError' => $registrantContext['access_error'],
73	            'replayPresentation' => $replayPresentation,
74	        ])->header(
75	            'Content-Security-Policy',
76	            $this->replayFramePolicy(),
77	        );
78	    }
79	
80	    private function shouldHideCompletely(Event $event): bool
81	    {
82	        return $event->state->isPubliclyHidden();
83	    }
84	
85	    private function shellFor(Event $event): string
86	    {
87	        return $event->state->publicShell($event->cancelled_at !== null);
88	    }
89	
90	    private function registrationOpen(Event $event, ?Registration $registrant): bool
91	    {
92	        return $event->cancelled_at === null
93	            && $event->state === EventState::PUBLISHED
94	            && $registrant === null;
95	    }
96	
97	    /**
98	     * Story 3-11 / FR106 / AC2 + AC5 — resolve and validate the event locale.
99	     *
100	     * Returns the event's configured locale if it is in the supported set,
101	     * otherwise falls back to the app default. Never throws.
102	     */
103	    private function resolveEventLocale(Event $event): string
104	    {
105	        return LocaleResolver::resolve($event->default_locale);
106	    }
107	
108	    /**
109	     * @return array{registration: ?Registration, viewer_shell: ?string, access_error: ?string}
110	     */
111	    private function resolveRegistrantContext(Event $event, Request $request): array
112	    {
113	        $registrationUuid = $request->query('registration');
114	        if (! is_string($registrationUuid) || trim($registrationUuid) === '') {
115	            return [
116	                'registration' => null,
117	                'viewer_shell' => null,
118	                'access_error' => null,
119	            ];
120	        }
121	
122	        if (! $this->registrantAccessUrls->validForRequest($event, $request, $registrationUuid)) {
123	            return [
124	                'registration' => null,
125	                'viewer_shell' => null,
126	                'access_error' => __('events.public_registration.viewer.invalid_link'),
127	            ];
128	        }
129	
130	        $registration = $this->eventService->findPublicRegistrant($event, $registrationUuid);
131	
132	        if ($registration === null) {
133	            return [
134	                'registration' => null,
135	                'viewer_shell' => null,
136	                'access_error' => __('events.public_registration.viewer.invalid_link'),
137	            ];
138	        }
139	
140	        return [
141	            'registration' => $registration,
142	            'viewer_shell' => $event->state->registrantViewerMode(),
143	            'access_error' => null,
144	        ];
145	    }
146	
147	    private function replayFramePolicy(): string
148	    {
149	        $configured = trim((string) config(
150	            'services.streaming.vimeo_player_origin',
151	            'https://player.vimeo.com',
152	        ));
153	        $parts = parse_url($configured);
154	        $origin = is_array($parts)
155	            && ($parts['scheme'] ?? null) === 'https'
156	            && ($parts['host'] ?? null) === 'player.vimeo.com'
157	            && ! isset($parts['port'])
158	            && ! isset($parts['user'])
159	            && ! isset($parts['pass'])
160	            && ! isset($parts['path'])
161	            && ! isset($parts['query'])
162	            && ! isset($parts['fragment'])
163	                ? $configured
164	                : 'https://player.vimeo.com';
165	
166	        return "frame-src 'self' {$origin}; object-src 'none'; base-uri 'self'";
167	    }
168	}
