@endphp

<div class="min-h-screen bg-white" style="font-family: 'Poppins', sans-serif;" data-testid="public-landing-page">
    @if($registrant !== null && in_array($viewerShell, ['registered', 'live', 'ended'], true))
        {{--
            Bug fix — <livewire:events.viewer-lifecycle-monitor> posts its
            check() poll-on-signal call through the public, unauthenticated
            public.livewire.update endpoint (see AllowPublicEngagementComponents
            ALLOWED_COMPONENTS/ALLOWED_METHODS). That only works when the
            data-livewire-public-update override span (see
            events::public.partials.livewire-public-update) has already
            rendered on the page — otherwise the client falls back to the
            default AUTH-ONLY livewire/update endpoint and check() 403s, so the
            waiting room never auto-transitions to LIVE.

            On the 'live' and 'ended' shells every template (classic/modern/bold)
            already includes events::public.partials.viewer-engagement for a
            registered viewer (the 'ended' shell renders it inside the same
            `$registrant !== null` guard this whole block is already gated on),
            which renders that SAME span — so we skip it here to avoid a
            duplicate DOM node. On the 'registered' (waiting-room) shell NO
            template renders viewer-engagement (there is no chat/Q&A/poll
            surface to show yet), so nothing else emits the span unless we do
            it here, immediately ahead of the monitor mount.

            'ended' closes the ENDED-shell gap: a replay viewer who lands on
            the page after the event has already ended now also gets the
            monitor mounted, so a later ENDED→SUSPENDED transition (legal per
            docs/specs/event-states.md) reaches them without a manual reload —
            see the (now-updated) comment on
            EngagementChannelAuthorizer::canSubscribeViewerLifecycle().
        --}}
        @if($viewerShell === 'registered')
            @include('events::public.partials.livewire-public-update')
        @endif
        <livewire:events.viewer-lifecycle-monitor
            :event="$event"
            :initial-shell="$viewerShell"
            :registration-uuid="$registrant->uuid"
        />
    @endif
    @if($shell === 'suspended')
        <section class="flex min-h-screen items-center justify-center bg-[#F3F0F0] px-6 text-center" data-testid="public-landing-suspended">
            <div class="w-full max-w-[480px] rounded-[16px] bg-white p-10 shadow-lg">
