                <p class="mt-3 text-[14px] text-[#4F4F4F]">{{ __('events.public_landing.suspended_body') }}</p>
            </div>
        </section>
    @elseif($shell === 'cancelled')
        <section class="flex min-h-screen items-center justify-center bg-[#F3F0F0] px-6 text-center" data-testid="public-landing-cancelled">
