                <p class="mt-3 text-[14px] text-[#4F4F4F]">{{ __('events.public_landing.cancelled_body') }}</p>
            </div>
        </section>
    @else

        @include("events::public.templates.$template", get_defined_vars())

        {{-- CTA block --}}
        @if($showPublicMarketingContent && ($cta['visible'] ?? false) === true && ! empty($cta['label']) && ! empty($cta['url']))
            <section data-testid="landing-preview-cta" class="{{ $template === 'modern' ? 'text-center py-4' : 'px-10 lg:px-28 py-4' }}">
                <a href="{{ $cta['url'] }}" target="_blank" rel="noreferrer"
                   class="inline-flex items-center justify-center gap-2 rounded-[12px] px-8 py-4 text-base font-bold text-white shadow-lg hover:shadow-xl transition-all hover:-translate-y-0.5"
                   style="background-color: {{ $accent }};">
                    {{ $cta['label'] }}
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/>
                    </svg>
                </a>
            </section>
        @endif

        {{-- FAQ block --}}
        @if($showPublicMarketingContent && ($faq['visible'] ?? false) === true && ! empty($faq['items']) && $registrationOpen)
            <section class="px-10 lg:px-28 pb-16" data-testid="landing-preview-faq">
                <div class="mx-auto max-w-[760px] space-y-3">
                    @foreach($faq['items'] as $item)
                        <details class="rounded-[12px] border border-[#E0E0E0] bg-white px-4 py-3">
                            <summary class="cursor-pointer text-[14px] font-semibold text-jako-heading">{{ $item['question'] ?? '' }}</summary>
                            @if(! empty($item['answer']))
                                <p class="mt-2 text-[14px] text-[#4F4F4F]">{{ $item['answer'] }}</p>
                            @endif
                        </details>
                    @endforeach
                </div>
            </section>
        @endif

        {{-- Footer --}}
        <footer class="flex items-center justify-center border-t border-gray-100 bg-[#F3F0F0] px-4 py-6 text-center text-[12px] text-[#828282] sm:justify-start sm:px-10 sm:text-left">
            <span>{!! __('events.public_landing.powered_by_html', ['year' => now()->year]) !!}</span>
        </footer>
    @endif
</div>
@endsection

