3	declare(strict_types=1);
4	
5	namespace Platform\Authz\Http;
6	
7	use Closure;
8	use Illuminate\Contracts\Auth\Authenticatable;
9	use Illuminate\Http\Request;
10	use Illuminate\Support\Facades\Gate;
11	use Symfony\Component\HttpFoundation\Response;
12	
13	class RouteCapabilityMiddleware
14	{
15	    private const REQUEST_EVALUATED_ATTRIBUTE = 'platform_authz.route_capability_evaluated';
16	
17	    public function __construct(
18	        private readonly RouteRequirementResolver $resolver,
19	    ) {}
20	
21	    public function handle(Request $request, Closure $next): Response
22	    {
23	        if ($request->attributes->get(self::REQUEST_EVALUATED_ATTRIBUTE) === true) {
24	            return $next($request);
25	        }
26	
27	        $request->attributes->set(self::REQUEST_EVALUATED_ATTRIBUTE, true);
28	
29	        $routeName = $request->route()?->getName();
30	
31	        if (!$routeName) {
32	            abort(403, 'Route must be named for permission checks.');
33	        }
34	
35	        $requirement = $this->resolver->resolve($routeName);
36	
37	        // A protected named route without an explicit route-permission mapping is a
38	        // configuration error. Fail closed rather than silently widening access.
39	        if ($requirement === null) {
40	            abort(403, 'Route permission mapping is missing for this route.');
41	        }
42	
43	        // Public routes bypass all auth/capability checks — the route is
44	        // open to all visitors, authenticated or not.
45	        if ($requirement->type === RouteRequirement::TYPE_PUBLIC) {
46	            return $next($request);
47	        }
48	
49	        $user = $request->user();
50	
51	        if (!$user) {
52	            abort(403, 'Authentication required.');
53	        }
54	
55	        if (!$this->evaluate($requirement, $user)) {
56	            abort(403, 'You do not have permission to access this route.');
57	        }
58	
59	        return $next($request);
60	    }
61	
62	    public function evaluate(RouteRequirement $requirement, Authenticatable $user): bool
63	    {
64	        return match ($requirement->type) {
65	            RouteRequirement::TYPE_PUBLIC => true,
66	            RouteRequirement::TYPE_NONE => true,
67	            RouteRequirement::TYPE_SINGLE => $this->evaluateSingle($requirement, $user),
68	            RouteRequirement::TYPE_ANY_OF => $this->evaluateAnyOf($requirement, $user),
69	            RouteRequirement::TYPE_ALL_OF => $this->evaluateAllOf($requirement, $user),
70	            RouteRequirement::TYPE_SPECIAL => $this->evaluateSpecial($requirement, $user),
71	            default => false,
72	        };
73	    }
74	
75	    private function evaluateSingle(RouteRequirement $requirement, Authenticatable $user): bool
76	    {
77	        return Gate::forUser($user)->allows($requirement->capabilities[0]);
78	    }
79	
80	    private function evaluateAnyOf(RouteRequirement $requirement, Authenticatable $user): bool
81	    {
82	        foreach ($requirement->capabilities as $capability) {
83	            if (Gate::forUser($user)->allows($capability)) {
84	                return true;
85	            }
86	        }
87	        return false;
88	    }
89	
90	    private function evaluateAllOf(RouteRequirement $requirement, Authenticatable $user): bool
91	    {
92	        foreach ($requirement->clauses as $clause) {
93	            if (!$this->evaluate($clause, $user)) {
94	                return false;
95	            }
96	        }
97	        return true;
98	    }
99	
100	    private function evaluateSpecial(RouteRequirement $requirement, Authenticatable $user): bool
101	    {
102	        $method = $requirement->specialMethod;
103	        if ($method === null || !method_exists($user, $method)) {
104	            return false;
105	        }
106	        return (bool) $user->$method();
107	    }
108	}
