5	namespace App\Modules\Events\Services;
6	
7	use App\Modules\Events\Enums\EventCustomDomainScope;
8	use App\Modules\Events\Models\Event;
9	use App\Modules\Events\Models\EventCustomDomain;
10	use App\Modules\Events\Models\Registration;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Carbon;
13	use Illuminate\Support\Facades\URL;
14	
15	final class RegistrantAccessUrlService
16	{
17	    public function __construct(
18	        private readonly EventCustomDomainService $customDomains,
19	    ) {}
20	
21	    public function forRegistration(
22	        Event $event,
23	        Registration $registration,
24	        Carbon $expiresAt,
25	    ): string {
26	        $domain = $this->customDomains->activeDomainForEvent($event);
27	
28	        if (! $domain instanceof EventCustomDomain) {
29	            return URL::temporarySignedRoute(
30	                'events.public.show',
31	                $expiresAt,
32	                [
33	                    'eventUuid' => $event->uuid,
34	                    'registration' => $registration->uuid,
35	                ],
36	            );
37	        }
38	
39	        $host = $domain->hostname_normalized;
40	        $path = $domain->scope === EventCustomDomainScope::EVENT
41	            ? '/'
42	            : $this->customDomains->hubPathForEvent($domain, $event);
43	        $expires = $expiresAt->getTimestamp();
44	        $signature = $this->signature(
45	            $host,
46	            $path,
47	            $event->uuid,
48	            $registration->uuid,
49	            $expires,
50	        );
51	
52	        return 'https://'.$host.$path.'?'.http_build_query([
53	            'event_uuid' => $event->uuid,
54	            'registration' => $registration->uuid,
55	            'intended_host' => $host,
56	            'expires' => $expires,
57	            'custom_signature' => $signature,
58	        ], '', '&', PHP_QUERY_RFC3986);
59	    }
60	
61	    public function validForRequest(
62	        Event $event,
63	        Request $request,
64	        string $registrationUuid,
65	    ): bool {
66	        $customSignature = $request->query('custom_signature');
67	        $intendedHost = $request->query('intended_host');
68	        $eventUuid = $request->query('event_uuid');
69	        $expires = $request->query('expires');
70	
71	        if (
72	            ! is_string($customSignature)
73	            || ! is_string($intendedHost)
74	            || ! is_string($eventUuid)
75	            || ! is_scalar($expires)
76	        ) {
77	            return $request->hasValidSignature();
78	        }
79	
80	        $requestHost = strtolower(rtrim($request->getHost(), '.'));
81	        $intendedHost = strtolower(rtrim($intendedHost, '.'));
82	        $expires = filter_var($expires, FILTER_VALIDATE_INT);
83	        if (
84	            $requestHost === ''
85	            || ! hash_equals($requestHost, $intendedHost)
86	            || ! hash_equals($event->uuid, strtolower($eventUuid))
87	            || $expires === false
88	            || $expires < now()->getTimestamp()
89	        ) {
90	            return false;
91	        }
92	
93	        $domain = $this->customDomains->activeDomainForHost($requestHost);
94	        if (
95	            ! $domain instanceof EventCustomDomain
96	            || (int) $domain->team_id !== (int) $event->team_id
97	            || (
98	                $domain->scope === EventCustomDomainScope::EVENT
99	                && (int) $domain->event_id !== (int) $event->id
100	            )
101	        ) {
102	            return false;
103	        }
104	
105	        $path = $request->getPathInfo();
106	        $expectedPath = $domain->scope === EventCustomDomainScope::EVENT
107	            ? '/'
108	            : $this->customDomains->hubPathForEvent($domain, $event);
109	        if (! hash_equals($expectedPath, $path)) {
110	            return false;
111	        }
112	
113	        return hash_equals(
114	            $this->signature(
115	                $requestHost,
116	                $path,
117	                $event->uuid,
118	                $registrationUuid,
119	                $expires,
120	            ),
121	            $customSignature,
122	        );
123	    }
124	
125	    private function signature(
126	        string $host,
127	        string $path,
128	        string $eventUuid,
129	        string $registrationUuid,
130	        int $expires,
131	    ): string {
132	        $payload = implode("\n", [
133	            'registrant-access-v1',
134	            strtolower($host),
135	            $path,
136	            strtolower($eventUuid),
137	            strtolower($registrationUuid),
138	            (string) $expires,
139	        ]);
140	
141	        return hash_hmac('sha256', $payload, (string) config('app.key'));
142	    }
143	}
