25	return Application::configure(basePath: dirname(__DIR__))
26	    ->withEvents(discover: false)
27	    ->withRouting(
28	        web: __DIR__.'/../routes/web.php',
29	        api: __DIR__.'/../routes/api.php',
30	        commands: __DIR__.'/../routes/console.php',
31	        health: '/up',
32	        then: function (): void {
33	            // Story 1-7a H-min — signature-only provider webhooks. Lives under
34	            // /api/webhooks/* to match the CSRF exclusion configured below.
35	            Route::prefix('api')
36	                ->middleware('api')
37	                ->group(__DIR__.'/../routes/webhooks.php');
38	        },
39	    )
40	    ->withMiddleware(function (Middleware $middleware): void {
41	        $middleware->alias([
42	            'route.permission' => RouteCapabilityMiddleware::class,
43	            'workspace.active' => WorkspaceStatusGuard::class,
44	        ]);
45	
46	        // Exclude webhook routes from CSRF verification
47	        $middleware->validateCsrfTokens(except: [
48	            'api/webhooks/*',
49	        ]);
50	
51	        // Resolve locale AFTER StartSession (default web group order) and
52	        // before app-custom web middleware that may flash translated copy.
53	        // Auto-login middleware must come early, before Fortify's auth
54	        // middleware on the route can reject unauth'd users clicking the
55	        // verification link. It still runs AFTER StartSession so the auth
56	        // guard can persist the session.
57	        //
58	        // IMPORTANT: do NOT prepend SetLocaleFromUser to this call.
59	        // Middleware::web(prepend:) places it BEFORE StartSession in the
60	        // resolved web group, so SessionGuard cannot resolve the user from
61	        // the session cookie and App::setLocale falls back to the default.
62	        // The in-memory auth cache in the test harness with the array
63	        // session driver masks this; production (file/redis/database
64	        // session drivers) does not.
65	        $middleware->web(
66	            append: [
67	                AutoLoginForEmailVerification::class,
68	                SetLocaleFromUser::class,
69	                LogAuthorizationFailures::class,
70	                SurfaceWorkspaceRemovalNotice::class,
71	                ResolveEventCustomDomain::class,
72	                RouteCapabilityMiddleware::class,
73	            ],
